 const ce=Math.cos(el),se=Math.sin(el),sa=Math.sin(az),ca=Math.cos(az),n=[ce*sa,ce*ca,se];
 let rx=0,ry=0,rz=0,ix=0,iy=0,iz=0,mrx=0,mry=0,mrz=0,mix=0,miy=0,miz=0;
 for(const g of m.segments){const p=g.p,v=g.v,a=m.k*(n[0]*p[0]+n[1]*p[1]+n[2]*p[2])+g.phase,c=Math.cos(a),q=Math.sin(a);
  rx+=v[0]*c;ry+=v[1]*c;rz+=v[2]*c;ix+=v[0]*q;iy+=v[1]*q;iz+=v[2]*q;
  if(grounded){const a2=m.k*(n[0]*p[0]+n[1]*p[1]-n[2]*p[2])+g.phase,c2=Math.cos(a2),q2=Math.sin(a2);mrx-=v[0]*c2;mry-=v[1]*c2;mrz+=v[2]*c2;mix-=v[0]*q2;miy-=v[1]*q2;miz+=v[2]*q2;}
 }
